function transfer(a,bytes,reads=0){a.write(I2C+0x18,3<<12);a.write(I2C+0x24,0xffffffff);for(const b of bytes)a.write(I2C+0x1c,b);const cmd=[6<<11,1<<11|1<<8|bytes.length,...(reads?[3<<11|reads]:[]),2<<11];cmd.forEach((v,i)=>a.write(I2C+0x58+4*i,v));a.write(I2C+4,1<<5);a.li(1,I2C+0x20);a.emit(0x0000a183,0x4801f193,0xfe018ce3);for(let i=0;i<reads;i++)a.copy(I2C+0x1c,RESULT+4*i);}
