  a.write(0x500e6018,1<<6);for(const[o,v]of[[0,17],[8,3],[0x38,4],[0x20,DESC+0x100],[0x1c,1<<21],[0x500,17],[0x508,3],[0x53c,3],[0x520,DESC+0x140],[0x51c,1<<22]])a.write(0x50088000+o,v);
