  a.li(1,RESULT+8);a.emit(1<<15|2<<12|2<<7|3);a.li(1,FB+2*721);a.emit(2<<20|1<<15|1<<12|0x23);dma(a);a.delay(16000000);uart(a,'TAB5_TOUCH\n');
  a.label('no_touch');transfer(a,[0x28,0x81,0x4e,0]);a.delay(4000000);a.jump('scan');
  const code=a.finish(),head=new Uint8Array(24),hv=new DataView(head.buffer);head.set([0xe9,2,0,0x40]);hv.setUint32(4,ENTRY,true);hv.setUint16(12,18,true);hv.setUint16(15,100,true);hv.setUint16(17,199,true);
